def num_islands(grid):
    if not grid:
        return 0
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    def sink(r, c):
        stack = [(r, c)]
        while stack:
            cr, cc = stack.pop()
            if cr < 0 or cc < 0 or cr >= rows or cc >= cols or grid[cr][cc] != 1:
                continue
            grid[cr][cc] = 0
            stack.extend([(cr + 1, cc), (cr - 1, cc), (cr, cc + 1), (cr, cc - 1)])
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1:
                sink(r, c)
                count += 1
    return count

reference_solution:
def num_islands(grid):
    if not grid:
        return 0
    grid = [row[:] for row in grid]
    rows, cols = len(grid), len(grid[0])
    visited = set()
    def dfs(r, c):
        if r < 0 or c < 0 or r >= rows or c >= cols:
            return
        if grid[r][c] != 1 or (r, c) in visited:
            return
        visited.add((r, c))
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)
    count = 0
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                dfs(r, c)
                count += 1
    return count
